//! Gap H3 parity: executes the REAL guest ELF in the SP1 zkVM (no proof) for every fixture in
//! `packages/zk/fixtures/sp1-quote-fixtures.json` (generated by the TypeScript pipeline) and requires the
//! committed public values to equal the TypeScript `encodeQuotePublicValues` byte-for-byte.
//!   cargo run --release --bin parity
#[allow(unused_imports)]
use sp1_sdk::{
    blocking::{ProveRequest, Prover, ProverClient},
    include_elf, Elf, SP1Stdin,
};
use serde_json::Value;

const GUEST_ELF: Elf = include_elf!("zguard-sp1-quote-guest");
const FIXTURES: &str = include_str!("../../../fixtures/sp1-quote-fixtures.json");
const HINT_ORDER: [&str; 4] = ["asset_mismatch", "chain_mismatch", "unexpected_approval", "domain_verified"];

fn main() {
    sp1_sdk::utils::setup_logger();
    let client = ProverClient::from_env();
    let fixtures: Value = serde_json::from_str(FIXTURES).expect("fixtures json");
    let list = fixtures.as_array().expect("fixtures array");
    let mut failures = 0usize;

    for f in list {
        let name = f["name"].as_str().expect("name");
        let mut stdin = SP1Stdin::new();
        // Same order as sp1-quote-guest/src/main.rs reads them.
        stdin.write(&f["quoteJson"].as_str().expect("quoteJson").as_bytes().to_vec());
        stdin.write(&f["txJson"].as_str().expect("txJson").as_bytes().to_vec());
        for k in HINT_ORDER {
            stdin.write(&f["hints"][k].as_bool().expect("hint"));
        }

        let (output, report) = client.execute(GUEST_ELF, stdin).run().expect("guest execution failed");
        let got = format!("0x{}", hex::encode(output.as_slice()));
        let want = f["expectedPublicValues"].as_str().expect("expectedPublicValues");
        let cycles = report.total_instruction_count();
        if got == want {
            println!("PASS {name:<34} ts={:<7} cycles={cycles}", f["tsVerdict"].as_str().unwrap_or("?"));
        } else {
            failures += 1;
            println!("FAIL {name}\n  guest: {got}\n  ts:    {want}");
        }
    }

    println!("{} / {} fixtures match", list.len() - failures, list.len());
    if failures > 0 {
        std::process::exit(1);
    }
}
